DECLARE entries jsonb := '{"balanceBlocks":[{"id":"logic-balance","content_version":1,"title":"Chiếc cân bí mật","stage":"Khám phá","prompt":"Một hộp nặng bằng 4 khối. Thả khối vào đĩa trống để cân bằng.","hint_levels":["Mỗi khối nặng 1 đơn vị. Quan sát độ nghiêng của cân."],"explanation":"Hai bên cùng nặng 4 đơn vị nên cân thăng bằng.","mechanism":"balanceBlocks","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"blocks":0},"skill_ids":[]},{"id":"logic-hidden","content_version":1,"title":"Hiệu chuẩn hộp bí mật","stage":"Thử thách","prompt":"Hộp mới có khối lượng khác trước. Thêm hoặc lấy khối đơn vị để tìm lúc cân nằm ngang.","hint_levels":["Dùng chiều nghiêng làm phản hồi; khi thêm quá nhiều, hãy lấy bớt."],"explanation":"Cân bằng cho thấy hai bên có cùng khối lượng: hộp này bằng 6 khối đơn vị.","mechanism":"balanceBlocks","mechanism_version":1,"evaluator_version":1,"config":{"target":6},"initial_state":{"blocks":1},"skill_ids":[]}],"removeBothSides":[{"id":"logic-remove","content_version":1,"title":"Bóc từng lớp","stage":"Khám phá","prompt":"x + 3 = 7. Vuốt bỏ từng cặp khối ở hai vế để tìm x.","hint_levels":["Mỗi lần bỏ cùng 1 khối ở cả hai bên, đẳng thức vẫn đúng."],"explanation":"Bỏ 3 ở cả hai vế: x = 4.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"logic-invariant","content_version":1,"title":"Giữ nguyên sự cân bằng","stage":"Vận dụng","prompt":"Mô hình đang biểu diễn x + 5 = 9. Giữ cân bằng và cô lập x bằng cách bỏ cùng một lượng ở hai vế.","hint_levels":["Quan sát lượng còn cộng với x. Mỗi thao tác phải giữ hai vế bằng nhau."],"explanation":"Bớt 5 ở cả hai vế bảo toàn đẳng thức: x = 4. Giá trị thay đổi, quy tắc cân bằng vẫn giữ nguyên.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{"extra":5,"total":9},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"algebra-isolate","content_version":1,"title":"Ẩn số sau những khối","stage":"Vận dụng","prompt":"Mô hình đang biểu diễn x + 2 = 8. Giữ cân bằng và cô lập x bằng cách bỏ cùng một lượng ở hai vế.","hint_levels":["Quan sát lượng còn cộng với x. Mỗi thao tác phải giữ hai vế bằng nhau."],"explanation":"Bớt 2 ở cả hai vế bảo toàn đẳng thức: x = 6. Giá trị thay đổi, quy tắc cân bằng vẫn giữ nguyên.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{"extra":2,"total":8},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"algebra-transfer","content_version":1,"title":"Thay số, giữ quy tắc","stage":"Vận dụng","prompt":"Mô hình đang biểu diễn x + 4 = 10. Giữ cân bằng và cô lập x bằng cách bỏ cùng một lượng ở hai vế.","hint_levels":["Quan sát lượng còn cộng với x. Mỗi thao tác phải giữ hai vế bằng nhau."],"explanation":"Bớt 4 ở cả hai vế bảo toàn đẳng thức: x = 6. Giá trị thay đổi, quy tắc cân bằng vẫn giữ nguyên.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{"extra":4,"total":10},"initial_state":{"pairs":0},"skill_ids":[]}],"gearRatios":[{"id":"logic-gears","content_version":1,"title":"Truyền chuyển động","stage":"Khám phá","prompt":"Bánh nhỏ có 12 răng, bánh lớn có 24 răng. Xoay bánh nhỏ để bánh lớn quay đúng một vòng.","hint_levels":["Bánh lớn cần số răng gấp đôi bánh nhỏ đi qua điểm tiếp xúc."],"explanation":"Bánh 12 răng quay 2 vòng thì bánh 24 răng quay 1 vòng, theo chiều ngược lại.","mechanism":"gearRatios","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"turns":0},"skill_ids":[]}],"logicalCounterexample":[{"id":"logic-counterexample","content_version":1,"title":"Một trường hợp đủ để bác bỏ","stage":"Thử thách","prompt":"Có người nói: “Đèn A sáng thì đèn B luôn sáng”. Bật/tắt hai đèn để tạo một phản ví dụ.","hint_levels":["Muốn bác bỏ quy tắc, điều kiện đầu phải xảy ra nhưng kết luận không xảy ra."],"explanation":"A sáng và B tắt là phản ví dụ. Khi A tắt, trường hợp đó không bác bỏ mệnh đề “nếu A thì B”.","mechanism":"logicalCounterexample","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"a":false,"b":false},"skill_ids":[]}],"fractionPaint":[{"id":"math-paint","content_version":1,"title":"Miếng bánh của bạn","stage":"Khám phá","prompt":"Tô đúng 3/8 chiếc bánh. Chạm vào các lát để bật hoặc tắt màu.","hint_levels":["Mẫu số 8 cho biết chiếc bánh có 8 phần bằng nhau."],"explanation":"Ba phần trong tám phần bằng nhau biểu diễn 3/8.","mechanism":"fractionPaint","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"painted":[]},"skill_ids":["fractions.part-whole"]},{"id":"math-equivalent","content_version":1,"title":"Một phân số, hai cách viết","stage":"Vận dụng","prompt":"Biểu diễn 3/4 chiếc bánh. Tự tô trên chiếc bánh chia 8 lát bằng nhau.","hint_levels":["Đổi về những phần có mẫu số 8. Có thể chạm lại để bỏ màu một lát."],"explanation":"Phần tô là 6/8; phần chưa tô là 2/8. Một tổng thể cho phép diễn tả cả phần và phần bù.","mechanism":"fractionPaint","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"painted":[]},"skill_ids":[]},{"id":"math-complement","content_version":1,"title":"Tìm phần còn lại","stage":"Vận dụng","prompt":"Tô sao cho phần CHƯA tô chiếm 3/8 chiếc bánh. Tự tô trên chiếc bánh chia 8 lát bằng nhau.","hint_levels":["Đổi về những phần có mẫu số 8. Có thể chạm lại để bỏ màu một lát."],"explanation":"Phần tô là 5/8; phần chưa tô là 3/8. Một tổng thể cho phép diễn tả cả phần và phần bù.","mechanism":"fractionPaint","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"painted":[]},"skill_ids":[]}],"fractionFold":[{"id":"math-fold","content_version":1,"title":"Gấp để chia","stage":"Khám phá","prompt":"Gấp tờ giấy thành những phần bằng nhau, để mỗi phần bằng 1/4 tờ ban đầu.","hint_levels":["Mỗi lần gấp đôi làm số phần tăng gấp đôi."],"explanation":"Hai lần gấp đôi tạo 4 phần bằng nhau: mỗi phần bằng 1/4.","mechanism":"fractionFold","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"folds":0},"skill_ids":["fractions.equal-parts"]}],"distributeObjects":[{"id":"math-share","content_version":1,"title":"Chuyến picnic","stage":"Khám phá","prompt":"Chia đều 9 quả cam vào 3 giỏ. Kéo từng quả đến giỏ bạn muốn.","hint_levels":["Mọi giỏ phải có cùng số quả và không còn quả bên ngoài."],"explanation":"9 chia 3 bằng 3: mỗi giỏ có 3 quả cam.","mechanism":"distributeObjects","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"baskets":[0,0,0]},"skill_ids":["fractions.equal-parts"]}],"fractionNumberLine":[{"id":"math-number-line","content_version":1,"title":"Phân số có một vị trí","stage":"Vận dụng","prompt":"Đặt điểm tại 3/4 đoạn đường từ 0 đến 1. Mỗi nấc là 1/8.","hint_levels":["Chia đoạn thành 4 phần bằng nhau rồi đi 3 phần. Hai nấc nhỏ tạo một phần tư."],"explanation":"3/4 = 6/8. Phân số biểu diễn một vị trí trên trục số, không chỉ là phần tô của chiếc bánh.","mechanism":"fractionNumberLine","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"position":0},"skill_ids":[]}],"launchAngle":[{"id":"science-launch","content_version":1,"title":"Cú phóng qua sông","stage":"Khám phá","prompt":"Xoay nòng pháo rồi phóng bóng đến cờ cách 10 m. Vận tốc cố định 10 m/s; g = 10 m/s².","hint_levels":["Tầm xa R = 10 × sin(2 × góc). Góc nào làm sin đạt 1?"],"explanation":"Ở 45°, tầm xa đạt tối đa 10 m trên mặt đất ngang, khi bỏ qua sức cản.","mechanism":"launchAngle","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"angle":20,"launched":false},"skill_ids":[]}],"motionTimeline":[{"id":"science-motion","content_version":1,"title":"Đạo diễn hành trình","stage":"Khám phá","prompt":"Lập hành trình: đi nhanh 2 giây, nghỉ 2 giây, rồi đi chậm 2 giây. Kéo các thẻ vào đường thời gian.","hint_levels":["Đi nhanh: 2 m/s; nghỉ: 0 m/s; đi chậm: 1 m/s."],"explanation":"Quãng đường là 2×2 + 0×2 + 1×2 = 6 m.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"science-distance","content_version":1,"title":"Cùng đích, khác hành trình","stage":"Thử thách","prompt":"Đi đúng 8 m và kết thúc bằng 2 giây nghỉ. Mỗi ô dài 2 giây; đi chậm 1 m/s, đi nhanh 2 m/s. Ghép thẻ rồi đọc đường đi.","hint_levels":["Quãng đường mỗi ô = tốc độ × 2. Thời gian nghỉ vẫn trôi, nhưng quãng đường không tăng."],"explanation":"Tổng quãng đường bằng tổng diện tích dưới từng đoạn tốc độ. Cùng một quãng đường có thể có nhiều lịch trình; các điều kiện phụ quyết định lịch trình phù hợp.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"science-return","content_version":1,"title":"Chậm trước, nhanh sau","stage":"Thử thách","prompt":"Đi đúng 6 m, bắt đầu đi chậm và kết thúc đi nhanh. Mỗi ô dài 2 giây; đi chậm 1 m/s, đi nhanh 2 m/s. Ghép thẻ rồi đọc đường đi.","hint_levels":["Quãng đường mỗi ô = tốc độ × 2. Thời gian nghỉ vẫn trôi, nhưng quãng đường không tăng."],"explanation":"Tổng quãng đường bằng tổng diện tích dưới từng đoạn tốc độ. Cùng một quãng đường có thể có nhiều lịch trình; các điều kiện phụ quyết định lịch trình phù hợp.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"optimization-budget","content_version":1,"title":"Ngân sách chuyển động","stage":"Thử thách","prompt":"Đi đúng 4 m với chỉ một ô đi nhanh; hai ô còn lại phải nghỉ. Mỗi ô dài 2 giây; đi chậm 1 m/s, đi nhanh 2 m/s. Ghép thẻ rồi đọc đường đi.","hint_levels":["Quãng đường mỗi ô = tốc độ × 2. Thời gian nghỉ vẫn trôi, nhưng quãng đường không tăng."],"explanation":"Tổng quãng đường bằng tổng diện tích dưới từng đoạn tốc độ. Cùng một quãng đường có thể có nhiều lịch trình; các điều kiện phụ quyết định lịch trình phù hợp.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]}],"leverTorque":[{"id":"science-lever","content_version":1,"title":"Cân bằng mômen","stage":"Khám phá","prompt":"Bên trái: 3 kg cách trục 2 m. Đặt quả nặng 2 kg ở bên phải để cân bằng.","hint_levels":["So sánh khối lượng × khoảng cách ở hai bên."],"explanation":"3 × 2 = 2 × 3. Quả 2 kg phải cách trục 3 m.","mechanism":"leverTorque","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"position":0},"skill_ids":[]}],"sortBars":[{"id":"data-sort","content_version":1,"title":"Đường chân trời","stage":"Khám phá","prompt":"Kéo các cột để sắp từ thấp đến cao, từ trái qua phải.","hint_levels":["Mỗi lần thả sẽ đổi chỗ hai cột."],"explanation":"Thứ tự tăng dần là 1, 2, 3, 4. Việc sắp xếp giúp nhìn ra phân bố dữ liệu.","mechanism":"sortBars","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"order":[3,1,4,2]},"skill_ids":[]}],"histogramBins":[{"id":"data-bins","content_version":1,"title":"Bưu điện dữ liệu","stage":"Khám phá","prompt":"Đưa các số 1, 2, 4, 5, 7, 8 vào đúng khoảng của biểu đồ.","hint_levels":["Khoảng đầu chứa 0–2, khoảng giữa chứa 3–5, khoảng cuối chứa 6–8."],"explanation":"Mỗi khoảng có 2 điểm. Tổng tần số là 6, bằng số dữ liệu ban đầu.","mechanism":"histogramBins","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"bins":[-1,-1,-1,-1,-1,-1]},"skill_ids":[]}],"redistributeMean":[{"id":"data-mean","content_version":1,"title":"San bằng thành phố","stage":"Khám phá","prompt":"Chuyển từng tầng giữa các tòa nhà để cả ba cao bằng nhau. Không thêm hoặc bớt tầng.","hint_levels":["Tổng là 12 tầng. Chia đều cho 3 tòa nhà."],"explanation":"Trung bình của 2, 4, 6 là (2 + 4 + 6)/3 = 4. Mọi tòa nhà cùng cao 4 tầng.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[2,4,6]},"skill_ids":[]},{"id":"data-outlier","content_version":1,"title":"San đều sau một ngoại lệ","stage":"Thử thách","prompt":"Làm ba tòa cao bằng nhau. Chuyển tầng giữa ba tòa; không được thêm hay bỏ tầng.","hint_levels":["Tổng số tầng được bảo toàn. Dùng tổng và quan hệ giữa các tòa để tìm mô hình phù hợp."],"explanation":"Tổng 12 tầng không đổi sau mỗi lần chuyển. Mô hình 4 – 4 – 4 thỏa đồng thời tổng và các quan hệ đề bài.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[1,2,9]},"skill_ids":[]},{"id":"data-distribution","content_version":1,"title":"Cùng trung bình, khác phân bố","stage":"Thử thách","prompt":"Giữ trung bình 4 tầng; tòa giữa cao 4 tầng, tòa phải gấp ba tòa trái. Chuyển tầng giữa ba tòa; không được thêm hay bỏ tầng.","hint_levels":["Tổng số tầng được bảo toàn. Dùng tổng và quan hệ giữa các tòa để tìm mô hình phù hợp."],"explanation":"Tổng 12 tầng không đổi sau mỗi lần chuyển. Mô hình 2 – 4 – 6 thỏa đồng thời tổng và các quan hệ đề bài.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[4,4,4]},"skill_ids":[]},{"id":"algebra-model","content_version":1,"title":"Giải bằng một thành phố","stage":"Thử thách","prompt":"Tòa giữa gấp đôi tòa trái; tòa phải gấp ba tòa trái. Tìm cả ba chiều cao. Chuyển tầng giữa ba tòa; không được thêm hay bỏ tầng.","hint_levels":["Tổng số tầng được bảo toàn. Dùng tổng và quan hệ giữa các tòa để tìm mô hình phù hợp."],"explanation":"Tổng 12 tầng không đổi sau mỗi lần chuyển. Mô hình 2 – 4 – 6 thỏa đồng thời tổng và các quan hệ đề bài.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[6,3,3]},"skill_ids":[]}],"outlierExplorer":[{"id":"data-median-outlier","content_version":1,"title":"Khi một điểm đi xa","stage":"Thử thách","prompt":"Bốn điểm cố định là 1, 2, 3, 4. Kéo điểm cuối để trung bình lớn hơn trung vị ít nhất 1 đơn vị.","hint_levels":["Trung vị là điểm thứ ba sau sắp xếp. Quan sát xem điểm cuối ảnh hưởng đến tổng như thế nào."],"explanation":"Điểm cuối từ 10 trở lên làm trung bình ít nhất bằng 4, trong khi trung vị vẫn là 3. Một ngoại lệ có thể kéo trung bình đi xa.","mechanism":"outlierExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"outlier":5},"skill_ids":[]}],"polygonVertices":[{"id":"geometry-rectangle","content_version":1,"title":"Kéo ra diện tích","stage":"Khám phá","prompt":"Di chuyển bốn đỉnh để tạo hình chữ nhật có diện tích 6 ô vuông.","hint_levels":["Thử một cạnh dài 3 ô và một cạnh dài 2 ô."],"explanation":"Diện tích hình chữ nhật bằng chiều dài nhân chiều rộng: 3 × 2 = 6.","mechanism":"polygonVertices","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"points":[[0,0],[4,0],[4,4],[0,4]]},"skill_ids":[]},{"id":"geometry-fence","content_version":1,"title":"Một mảnh vườn, hai điều kiện","stage":"Thử thách","prompt":"Kéo bốn đỉnh thành hình chữ nhật có diện tích 8 ô vuông và chu vi 12 đơn vị. Mỗi khoảng lưới dài 1 đơn vị.","hint_levels":["Tìm hai cạnh vừa có tích bằng 8, vừa có tổng bằng 6. Không chỉ kiểm tra diện tích."],"explanation":"Diện tích ràng buộc tích hai cạnh; chu vi ràng buộc tổng hai cạnh. Một mô hình phải đáp ứng cả hai điều kiện.","mechanism":"polygonVertices","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"points":[[0,0],[4,0],[4,4],[0,4]]},"skill_ids":[]},{"id":"geometry-square","content_version":1,"title":"Khi hình vuông xuất hiện","stage":"Thử thách","prompt":"Kéo bốn đỉnh thành hình chữ nhật có diện tích 9 ô vuông và chu vi 12 đơn vị. Mỗi khoảng lưới dài 1 đơn vị.","hint_levels":["Tìm hai cạnh vừa có tích bằng 9, vừa có tổng bằng 6. Không chỉ kiểm tra diện tích."],"explanation":"Diện tích ràng buộc tích hai cạnh; chu vi ràng buộc tổng hai cạnh. Một mô hình phải đáp ứng cả hai điều kiện.","mechanism":"polygonVertices","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"points":[[0,0],[4,0],[4,4],[0,4]]},"skill_ids":[]}],"symmetryMirror":[{"id":"geometry-mirror","content_version":1,"title":"Xưởng đối xứng","stage":"Khám phá","prompt":"Chạm các ô bên phải để phản chiếu hình xanh qua trục giữa.","hint_levels":["Mỗi ô ảnh cách trục một khoảng bằng ô gốc."],"explanation":"Phép đối xứng giữ nguyên hàng và đảo vị trí cột qua trục.","mechanism":"symmetryMirror","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"cells":[]},"skill_ids":[]}],"tangramRotate":[{"id":"geometry-tangram","content_version":1,"title":"Hai mảnh thành vuông","stage":"Khám phá","prompt":"Xoay hai tam giác, rồi kéo từng mảnh vào khung để ghép thành hình vuông.","hint_levels":["Hai cạnh huyền phải trùng nhau, hai góc vuông nằm ở hai góc đối diện."],"explanation":"Hai tam giác vuông bằng nhau ghép dọc cạnh huyền tạo thành hình vuông.","mechanism":"tangramRotate","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"turns":[1,1],"placed":[false,false]},"skill_ids":[]}],"solidExplorer":[{"id":"geometry-solid-volume","content_version":1,"title":"Xưởng khối không gian","stage":"Khám phá 3D","prompt":"Tạo khối hộp có thể tích 12 đơn vị khối và diện tích bề mặt 32 đơn vị vuông. Xoay khối để quan sát các mặt.","hint_levels":["Thể tích là dài × cao × sâu. Thử ba kích thước có tích bằng 12 rồi so sánh tổng diện tích sáu mặt."],"explanation":"Khối có các cạnh 2, 2, 3 thỏa V = 12 và S = 2 × (4 + 6 + 6) = 32. Đổi hướng khối không đổi hai đại lượng này.","mechanism":"solidExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"width":2,"height":2,"depth":2},"skill_ids":[]},{"id":"algebra-solid-relation","content_version":1,"title":"Một khối, ba quan hệ","stage":"Vận dụng 3D","prompt":"Dựng khối hộp có thể tích 16 đơn vị khối. Chiều dài gấp đôi chiều cao; chiều sâu bằng chiều cao.","hint_levels":["Cho chiều cao và chiều sâu bằng nhau trước. Mỗi khi đổi chiều cao, chiều dài cần thay đổi thế nào?"],"explanation":"Cao = sâu = 2 và dài = 4: thể tích là 4 × 2 × 2 = 16. Mô hình phải thỏa cả thể tích lẫn quan hệ giữa các cạnh.","mechanism":"solidExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"width":2,"height":2,"depth":2},"skill_ids":[]}],"robotRoute":[{"id":"coding-route","content_version":1,"title":"Dẫn robot về nhà","stage":"Khám phá","prompt":"Vuốt trên bản đồ hoặc thêm lệnh để dẫn robot từ góc trái trên tới ngôi sao. Tránh ô đá ở giữa.","hint_levels":["Đi theo mép trên rồi rẽ xuống. Bạn có thể xóa lệnh để thử lại."],"explanation":"Một thuật toán là chuỗi thao tác rõ ràng; thứ tự lệnh quyết định đường đi.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":[]},"skill_ids":[]},{"id":"coding-shortest","content_version":1,"title":"Tiết kiệm từng lệnh","stage":"Thử thách","prompt":"Dẫn robot tới sao bằng tối đa 6 lệnh, tránh đá và mép bản đồ.","hint_levels":["Mỗi bước chỉ thay đổi một tọa độ. Quan sát đường vẽ và loại các bước vòng lại không cần thiết."],"explanation":"Thuật toán tốt vừa đi đúng, vừa tuân thủ giới hạn tài nguyên. Đường đi của bạn vượt qua đá, đến đích và đáp ứng giới hạn 6 lệnh.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":[]},"skill_ids":[]},{"id":"coding-checkpoint","content_version":1,"title":"Ghé trạm trước khi về","stage":"Thử thách","prompt":"Dẫn robot tới sao bằng tối đa 6 lệnh, tránh đá và mép bản đồ. Trước khi tới đích, phải qua cột 1, hàng 3 (đếm từ góc trái trên).","hint_levels":["Mỗi bước chỉ thay đổi một tọa độ. Quan sát đường vẽ và loại các bước vòng lại không cần thiết."],"explanation":"Thuật toán tốt vừa đi đúng, vừa tuân thủ giới hạn tài nguyên. Đường đi của bạn vượt qua đá, đến đích và đáp ứng giới hạn 6 lệnh.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":[]},"skill_ids":[]},{"id":"optimization-debug","content_version":1,"title":"Gỡ lỗi đường đi","stage":"Thử thách","prompt":"Dẫn robot tới sao bằng tối đa 6 lệnh, tránh đá và mép bản đồ. Đường hiện tại có lỗi: dùng nút lùi để sửa.","hint_levels":["Mỗi bước chỉ thay đổi một tọa độ. Quan sát đường vẽ và loại các bước vòng lại không cần thiết."],"explanation":"Thuật toán tốt vừa đi đúng, vừa tuân thủ giới hạn tài nguyên. Đường đi của bạn vượt qua đá, đến đích và đáp ứng giới hạn 6 lệnh.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":["R","D"]},"skill_ids":[]}],"loopBuilder":[{"id":"coding-loop","content_version":1,"title":"Cầu thang vòng lặp","stage":"Khám phá","prompt":"Lắp hai lệnh và đặt số lần lặp để robot đi đúng cầu thang: sang phải rồi xuống, ba lần.","hint_levels":["Khối lặp giúp dùng hai lệnh để tạo ra sáu bước."],"explanation":"Lặp [phải, xuống] ba lần tạo đường cầu thang tới ô (3, 3).","mechanism":"loopBuilder","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"body":["D","R"],"repeat":1},"skill_ids":[]}],"sortingNetwork":[{"id":"coding-sort","content_version":1,"title":"Thiết kế máy sắp xếp","stage":"Khám phá","prompt":"Lắp tối đa 6 bộ so sánh giữa các dây kề nhau, rồi chạy máy. Mạng cần sắp đúng cả 24 thứ tự đầu vào.","hint_levels":["Mỗi bộ so sánh chỉ đổi chỗ khi số trên lớn hơn số dưới. Thử chuỗi 1–2, 2–3, 3–4, rồi xử lý ba dây đầu."],"explanation":"Một mạng sắp xếp dùng cùng chuỗi bộ so sánh cho mọi đầu vào. Mỗi bộ tự đưa số nhỏ lên trên; mạng này đã vượt qua cả 24 hoán vị.","mechanism":"sortingNetwork","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"stages":[],"result":[]},"skill_ids":[]},{"id":"optimization-network","content_version":1,"title":"Sửa máy, không sửa đầu vào","stage":"Thử thách","prompt":"Máy đã có ba bộ so sánh nhưng chưa sắp đúng mọi đầu vào. Chỉnh hoặc lắp thêm, tối đa 6 bộ; chạy kiểm tra cả 24 hoán vị.","hint_levels":["Một đầu vào chạy đúng chưa chứng minh máy đúng. Tìm cặp dây còn có thể đảo thứ tự sau mỗi lượt."],"explanation":"Máy được kiểm tra trên cả 24 hoán vị, không chỉ ví dụ đang hiển thị. Chuỗi bộ so sánh dùng lại được với mọi đầu vào.","mechanism":"sortingNetwork","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"stages":[0,1,2],"result":[]},"skill_ids":[]}],"wireCircuit":[{"id":"circuits-wire","content_version":1,"title":"Ánh sáng đầu tiên","stage":"Khám phá","prompt":"Đèn và nguồn đã gắn sẵn. Kéo hai dây để nối cực dương nguồn tới đầu vào đèn, rồi nối đầu ra đèn về cực âm.","hint_levels":["Cần dây 1–2 và dây 3–4. Đừng nối trực tiếp hai cực nguồn hoặc nối tắt hai đầu đèn."],"explanation":"Dòng điện cần một đường kín từ nguồn, qua tải và trở về nguồn.","mechanism":"wireCircuit","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"edges":[]},"skill_ids":[]}],"switchLogic":[{"id":"circuits-logic","content_version":1,"title":"Đường điện dự phòng","stage":"Khám phá","prompt":"Nhánh A đang bảo trì: giữ A mở. Bật đèn bằng nhánh B và công tắc chính C.","hint_levels":["A và B mắc song song, cả hai cùng đi qua C."],"explanation":"Mạch sáng khi (A HOẶC B) VÀ C. Với A mở, B và C đều phải đóng.","mechanism":"switchLogic","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"switches":[false,false,false]},"skill_ids":[]}],"colorMixer":[{"id":"circuits-light","content_version":1,"title":"Phòng pha ánh sáng","stage":"Khám phá","prompt":"Điều chỉnh ba chùm sáng để tạo màu vàng của mẫu.","hint_levels":["Ánh sáng đỏ cộng ánh sáng lục tạo vàng; ánh sáng lam làm màu nhạt đi."],"explanation":"Pha màu cộng: đỏ + lục = vàng. Đây là ánh sáng, khác pha sơn.","mechanism":"colorMixer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"rgb":[0.0,0.0,1.0]},"skill_ids":[]},{"id":"circuits-cyan","content_version":1,"title":"Trộn ra màu trời","stage":"Vận dụng","prompt":"Điều chỉnh ba nguồn sáng để khớp mẫu lục lam. Quan sát màu trộn khi tăng hoặc giảm từng nguồn.","hint_levels":["Thử bật từng cặp nguồn, rồi cả ba nguồn. Đây là pha ánh sáng cộng, không phải pha sơn."],"explanation":"Mẫu lục lam được tạo bởi mức đỏ–lục–lam 0% – 100% – 100%. Cộng các chùm sáng thay đổi cả sắc và độ sáng.","mechanism":"colorMixer","mechanism_version":1,"evaluator_version":1,"config":{"color":4278255615,"colorLabel":"Mẫu lục lam"},"initial_state":{"rgb":[0.0,0.0,0.0]},"skill_ids":[]},{"id":"circuits-white","content_version":1,"title":"Từ ba màu thành trắng","stage":"Vận dụng","prompt":"Điều chỉnh ba nguồn sáng để khớp mẫu trắng. Quan sát màu trộn khi tăng hoặc giảm từng nguồn.","hint_levels":["Thử bật từng cặp nguồn, rồi cả ba nguồn. Đây là pha ánh sáng cộng, không phải pha sơn."],"explanation":"Mẫu trắng được tạo bởi mức đỏ–lục–lam 100% – 100% – 100%. Cộng các chùm sáng thay đổi cả sắc và độ sáng.","mechanism":"colorMixer","mechanism_version":1,"evaluator_version":1,"config":{"color":4294967295,"colorLabel":"Mẫu trắng"},"initial_state":{"rgb":[0.0,0.0,0.0]},"skill_ids":[]}],"probabilityBag":[{"id":"probability-bag","content_version":1,"title":"Túi bí mật","stage":"Khám phá","prompt":"Thả đủ 6 viên vào túi để xác suất rút một viên xanh là 1/3.","hint_levels":["Trong 6 viên, cần 2 viên xanh. Các viên còn lại màu đỏ."],"explanation":"Có 2 kết quả xanh trên 6 viên đồng khả năng: 2/6 = 1/3.","mechanism":"probabilityBag","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"balls":[]},"skill_ids":[]},{"id":"probability-fair","content_version":1,"title":"Thiết kế một túi công bằng","stage":"Thử thách","prompt":"Hai màu phải có cơ hội xuất hiện bằng nhau. Dựng túi gồm đúng 8 viên bằng cách thêm hoặc lấy bi ra.","hint_levels":["Hai màu chia sẻ cùng một tổng. Chuyển điều kiện đề bài thành số viên của từng màu rồi kiểm tra lại cả túi."],"explanation":"Có 4 viên xanh và 4 viên đỏ, nên P(xanh) = 4/8. Cơ hội thay đổi khi tỉ lệ các màu thay đổi.","mechanism":"probabilityBag","mechanism_version":1,"evaluator_version":1,"config":{"capacity":8},"initial_state":{"balls":[]},"skill_ids":[]},{"id":"probability-odds","content_version":1,"title":"Cơ hội gấp ba","stage":"Thử thách","prompt":"Cơ hội rút xanh phải gấp ba cơ hội rút đỏ. Dựng túi gồm đúng 8 viên bằng cách thêm hoặc lấy bi ra.","hint_levels":["Hai màu chia sẻ cùng một tổng. Chuyển điều kiện đề bài thành số viên của từng màu rồi kiểm tra lại cả túi."],"explanation":"Có 6 viên xanh và 2 viên đỏ, nên P(xanh) = 6/8. Cơ hội thay đổi khi tỉ lệ các màu thay đổi.","mechanism":"probabilityBag","mechanism_version":1,"evaluator_version":1,"config":{"capacity":8},"initial_state":{"balls":[]},"skill_ids":[]}],"sampleSpace":[{"id":"probability-space","content_version":1,"title":"Bản đồ hai đồng xu","stage":"Khám phá","prompt":"Ghép từng cặp mặt xu vào bảng để liệt kê đủ các kết quả khi tung hai đồng xu có thứ tự.","hint_levels":["SN khác NS vì đồng thứ nhất và đồng thứ hai được phân biệt."],"explanation":"Không gian mẫu gồm SS, SN, NS, NN. Bốn kết quả có xác suất bằng nhau với xu cân đối.","mechanism":"sampleSpace","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"outcomes":[]},"skill_ids":[]}],"probabilitySpinner":[{"id":"probability-spinner","content_version":1,"title":"Thiết kế vòng quay","stage":"Khám phá","prompt":"Kéo tay nắm để phần màu xanh chiếm 3/8 vòng quay.","hint_levels":["Vòng quay được chia thành 8 cung bằng nhau; cần 3 cung xanh."],"explanation":"Xác suất trúng màu xanh bằng phần góc xanh trên cả vòng: 3 × 45° / 360° = 3/8.","mechanism":"probabilitySpinner","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"sectors":1},"skill_ids":[]}],"globeExplorer":[{"id":"geography-globe-grid","content_version":1,"title":"Tìm đường trên quả địa cầu","stage":"Khám phá 3D","prompt":"Đặt điểm tại 15° Bắc, 105° Đông trên quả địa cầu. Xoay để nhìn quanh, rồi chạm bề mặt hoặc điều chỉnh tọa độ.","hint_levels":["Vĩ độ Bắc nằm phía bắc xích đạo. Kinh độ Đông được đo về phía đông từ kinh tuyến gốc 0°."],"explanation":"Vĩ độ đo vị trí Bắc–Nam; kinh độ đo vị trí Đông–Tây. Xoay quả địa cầu chỉ đổi góc nhìn, không đổi tọa độ điểm.","mechanism":"globeExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"latitude":0,"longitude":0},"skill_ids":[]}],"strataExplorer":[{"id":"geography-rock-layers","content_version":1,"title":"Đọc lịch sử trong lớp đất đá","stage":"Vận dụng 3D","prompt":"Các lớp trầm tích chưa bị đảo lộn. Sắp lớp có tuổi 10, 20 và 30 triệu năm từ trên xuống dưới, theo thứ tự hình thành.","hint_levels":["Trong chuỗi trầm tích không bị đảo lộn, lớp bên dưới hình thành trước lớp phủ lên trên."],"explanation":"Từ trên xuống: 10, 20, 30 triệu năm. Mô hình giả định các lớp lắng đọng liên tiếp, chưa bị biến dạng hoặc đảo lộn.","mechanism":"strataExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"layers":[30,10,20]},"skill_ids":[]}]}'::jsonb; item record;
BEGIN
  FOR item IN SELECT key,value FROM jsonb_each(entries) LOOP
    IF EXISTS(SELECT 1 FROM private.evaluator_versions WHERE mechanism=item.key AND version=1
      AND status='active' AND implementation_hash<>'c9b96186271a5eff2cfc099c40ec450bf4846d3e58f49d3f4dd485a7baa21afc')
    THEN RAISE EXCEPTION 'An active evaluator is immutable; deploy a new evaluator version'; END IF;
    UPDATE private.evaluator_versions SET status='active',handler_key='learning-api:dart-v1',
      implementation_hash='c9b96186271a5eff2cfc099c40ec450bf4846d3e58f49d3f4dd485a7baa21afc',input_schema=jsonb_build_object('activities',item.value,'max_state_bytes',65536)
      WHERE mechanism=item.key AND version=1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Missing baseline evaluator: %',item.key; END IF;
  END LOOP;
END $registry$;
